	name, err := hooksLockFile(hooksDir)
	if err != nil {
		return nil, fmt.Errorf("%w: %w", errHooksLockUnavailable, err)
	}
	lockPath := filepath.Join(lockRoot.Name(), name)
	ctx, cancel := context.WithTimeout(ctx, hooksLockTimeout)
	defer cancel()
