package execx

import (
	"os/exec"
	"syscall"

	"golang.org/x/sys/windows"
)

// detachFromTTY configures cmd to run without an inherited console so any
// /dev/tty-style probe in the child fails. Sets CREATE_NEW_PROCESS_GROUP and
// DETACHED_PROCESS so the child has no console and no signal coupling.
func detachFromTTY(cmd *exec.Cmd) {
	if cmd.SysProcAttr == nil {
		cmd.SysProcAttr = &syscall.SysProcAttr{}
	}
	cmd.SysProcAttr.CreationFlags |= windows.CREATE_NEW_PROCESS_GROUP | windows.DETACHED_PROCESS
}

// killProcessGroupOnCancel is a no-op on Windows: reliable tree-kill needs a Job
// Object. The WaitDelay backstop still bounds the wait on a hung subprocess.
func killProcessGroupOnCancel(_ *exec.Cmd) {}
//go:build unix

package execx

import (
	"fmt"
	"os/exec"
	"syscall"
)

// detachFromTTY puts the child in a new session with no controlling terminal.
// Any subsequent open of /dev/tty by the child (or its descendants) fails.
func detachFromTTY(cmd *exec.Cmd) {
	if cmd.SysProcAttr == nil {
		cmd.SysProcAttr = &syscall.SysProcAttr{}
	}
	cmd.SysProcAttr.Setsid = true
}

// killProcessGroupOnCancel SIGKILLs the whole process group on ctx-cancel.
// exec.Cmd's default Cancel only kills the direct child, leaving any descendant
// (a sandbox or transport helper) alive and holding the output pipe open.
func killProcessGroupOnCancel(cmd *exec.Cmd) {
	if cmd.SysProcAttr == nil {
		cmd.SysProcAttr = &syscall.SysProcAttr{}
	}
	cmd.SysProcAttr.Setpgid = true
	cmd.Cancel = func() error {
		if cmd.Process == nil {
			return nil
		}
		// Negative PID = whole group (leader pid == pgid). ESRCH = already exited.
		if err := syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL); err != nil && err != syscall.ESRCH {
			return fmt.Errorf("kill process group: %w", err)
		}
		return nil
	}
}

